using System;

namespace ZeroGraphics.DirectX.Pipeline.Shaders
{
    /// <summary>
    /// Precompiled HLSL shader bytecode (Shader Model 4.0).
    /// Embedded directly to eliminate runtime compiler dependencies and file I/O.
    /// </summary>
    public static class ShaderBytecodes
    {
        private static readonly Lazy<byte[]> _vsBytecode = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        private static readonly Lazy<byte[]> _psBytecode = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        public static byte[] SdfVertexShaderBytecode => _vsBytecode.Value;
        public static byte[] SdfPixelShaderBytecode => _psBytecode.Value;
    }
}